public static void check(Solution solution) {
    assert Arrays.equals(solution.canBeIncreasing(new int[]{1,3,2,4,5}), True);
    assert Arrays.equals(solution.canBeIncreasing(new int[]{1,2,2,3,4,5}), True);
    assert Arrays.equals(solution.canBeIncreasing(new int[]{1,2,2,3}), True);
    assert Arrays.equals(solution.canBeIncreasing(new int[]{1,1,1}), False);
    assert Arrays.equals(solution.canBeIncreasing(new int[]{10,9,2,5,3,7,101,18}), False);
    assert Arrays.equals(solution.canBeIncreasing(new int[]{1,2,3,4,5,3}), True);
